BEGIN
  INSERT INTO auth.users (instance_id, id, aud, role, email, encrypted_password, raw_app_meta_data,
    raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new,
    email_change, is_sso_user, is_anonymous)
  SELECT '00000000-0000-0000-0000-000000000000', r.id, 'authenticated', 'authenticated', NULL, NULL, '{}'::jsonb,
    jsonb_build_object('full_name', r.display_name, 'avatar_url', r.avatar_url), r.created_at, r.created_at,
    '', '', '', '', false, false
  FROM jsonb_to_recordset(payload) AS r(id uuid, username text, display_name text, headline text, bio text, city text, state text, country text, roles text[], instruments text[], genres text[], languages text[], specialisations text[], avatar_url text, availability text, visibility text, links jsonb, created_at timestamptz)
  ON CONFLICT (id) DO NOTHING;

  -- on_auth_user_created has made a bare profile for each; fill it.
  INSERT INTO public.profiles (id, username, display_name, headline, bio, city, state, country, roles, instruments, genres, languages, specialisations, avatar_url, availability, visibility, links, created_at, onboarding_complete)
  SELECT r.id, r.username, r.display_name, r.headline, r.bio, r.city, r.state, r.country, r.roles, r.instruments, r.genres, r.languages, r.specialisations, r.avatar_url, r.availability, r.visibility, r.links, r.created_at, true
  FROM jsonb_to_recordset(payload) AS r(id uuid, username text, display_name text, headline text, bio text, city text, state text, country text, roles text[], instruments text[], genres text[], languages text[], specialisations text[], avatar_url text, availability text, visibility text, links jsonb, created_at timestamptz)
  ON CONFLICT (id) DO UPDATE SET username = EXCLUDED.username, display_name = EXCLUDED.display_name, headline = EXCLUDED.headline, bio = EXCLUDED.bio, city = EXCLUDED.city, state = EXCLUDED.state, country = EXCLUDED.country, roles = EXCLUDED.roles, instruments = EXCLUDED.instruments, genres = EXCLUDED.genres, languages = EXCLUDED.languages, specialisations = EXCLUDED.specialisations, avatar_url = EXCLUDED.avatar_url, availability = EXCLUDED.availability, visibility = EXCLUDED.visibility, links = EXCLUDED.links, onboarding_complete = true;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, username text, display_name text, headline text, bio text, city text, state text, country text, roles text[], instruments text[], genres text[], languages text[], specialisations text[], avatar_url text, availability text, visibility text, links jsonb, created_at timestamptz) JOIN public.profiles p ON p.id = r.id
      WHERE (p.username, p.display_name, p.headline, p.bio, p.city, p.state, p.country, p.roles, p.instruments, p.genres, p.languages, p.specialisations, p.avatar_url, p.availability, p.visibility, p.links) IS NOT DISTINCT FROM (r.username, r.display_name, r.headline, r.bio, r.city, r.state, r.country, r.roles, r.instruments, r.genres, r.languages, r.specialisations, r.avatar_url, r.availability, r.visibility, r.links))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'profile import: stored rows differ from the payload';
  END IF;
END
$import$;

