BEGIN
  INSERT INTO public.portfolio_items (id, user_id, title, kind, description, role, collaborators, cover_url, media_url, release_year, published, sort_order)
  SELECT r.id, r.user_id, r.title, r.kind, r.description, r.role, r.collaborators, r.cover_url, r.media_url, r.release_year, r.published, r.sort_order
  FROM jsonb_to_recordset(payload) AS r(id uuid, user_id uuid, title text, kind text, description text, role text, collaborators text[], cover_url text, media_url text, release_year int, published boolean, sort_order int)
  ON CONFLICT (id) DO NOTHING;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, user_id uuid, title text, kind text, description text, role text, collaborators text[], cover_url text, media_url text, release_year int, published boolean, sort_order int) JOIN public.portfolio_items p ON p.id = r.id
      WHERE (p.id, p.user_id, p.title, p.kind, p.description, p.role, p.collaborators, p.cover_url, p.media_url, p.release_year, p.published, p.sort_order) IS NOT DISTINCT FROM (r.id, r.user_id, r.title, r.kind, r.description, r.role, r.collaborators, r.cover_url, r.media_url, r.release_year, r.published, r.sort_order))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'portfolio import: stored rows differ from the payload';
  END IF;
END
$import$;

